-- stylua: ignore start
return {
  { "aaron", "亚伦 (Yàlún) - 希伯来语，意思是“开明”、“高尚”或“力量之山”。在《圣经》中，亚伦是摩西的哥哥。例如：美国职业棒球大联盟的著名球员 Aaron Judge (亚伦·贾吉)。" },
  { "abandoned", "被遗弃的 (bèi yí qì de) - 意思是“被抛弃”、“不再使用”。例如：一座被废弃的工厂 (An abandoned factory)。" },
  { "aberdeen", "阿伯丁 (Ābódīng) - 苏格兰东北部的港口城市，以石油工业和渔业闻名。例如：阿伯丁大学 (University of Aberdeen)。" },
  { "abilities", "能力 (nénglì) - 指一个人做某事的能力、才能或力量。例如：他有很强的学习能力 (He has a strong ability to learn)。" },
  { "ability", "能力 (nénglì) - 指一个人做某事的能力、才能或力量。例如：她有能力清楚地解释事情 (She has the ability to explain things clearly)。" },
  { "able", "能 (néng) - 表示有能力、有才干或有时间做某事。例如：他能胜任这项工作 (He is able to do this job well)。" },
  { "aboriginal", "土著的 (tǔzhù de) - 指某地区最早的居民。例如：澳大利亚土著居民 (Aboriginal Australians)。" },
  { "abortion", "堕胎 (duòtāi) - 指人为地中止妊娠。例如：关于堕胎的合法性，至今仍有很大的争议 (The legality of abortion is still a matter of great controversy)。" },
  { "about", "关于 (guānyú) - 表示“关于”或“在...方面”。例如：一本关于历史的书 (A book about history)。" },
  { "above", "在...之上 (zài...zhīshàng) - 表示位置高于某物。例如：飞机在云层之上飞行 (The plane is flying above the clouds)。" },
  { "abraham", "亚伯拉罕 (Yàbólāhǎn) - 《圣经》中的重要人物，被称为希伯来人的始祖，犹太教、基督教和伊斯兰教的共同先祖。例如：美国总统亚伯拉罕·林肯 (Abraham Lincoln)。" },
  { "abroad", "在国外 (zài guówài) - 表示在或去外国。例如：他正在国外出差 (He is currently abroad on business)。" },
  { "absence", "缺席 (quēxí) - 表示不在场或缺少。例如：他的缺席让大家很担心 (His absence made everyone worry)。" },
  { "absent", "缺席的 (quēxí de) - 表示不在场的。例如：他今天缺席了会议 (He was absent from the meeting today)。" },
  { "absolute", "绝对的 (juéduì de) - 表示完全的、无条件的。例如：我对他有绝对的信心 (I have absolute faith in him)。" },
  { "absolutely", "绝对地 (juéduì de) - 表示完全地、无条件地。例如：这绝对是正确的 (This is absolutely correct)。" },
  { "absorption", "吸收 (xīshōu) - 指一个物体吸收另一个物体的过程。例如：植物吸收水分 (Plants absorb water)。" },
  { "abstract", "抽象的 (chōuxiàng de) - 指不具体的、概念性的。例如：这是一个非常抽象的概念 (This is a very abstract concept)。" },
  { "abstracts", "摘要 (zhāiyào) - 对文章或报告的简短概括。例如：请先阅读摘要 (Please read the abstract first)。" },
  { "abuse", "滥用 (lànyòng) - 指不正当地使用或对待。例如：滥用权力 (Abuse of power)。" },
  { "academic", "学术的 (xuéshù de) - 与教育、学术或学习有关的。例如：他有很高的学术成就 (He has high academic achievements)。" },
  { "academics", "学者 (xuézhě) - 在大学里从事教学或研究的人。例如：许多学者都参加了这次会议 (Many academics attended the conference)。" },
  { "academy", "学院 (xuéyuàn) - 提供专业训练或高等教育的学校。例如：他毕业于一所著名的军事学院 (He graduated from a famous military academy)。" },
  { "accent", "口音 (kǒuyīn) - 一个人说话时特有的发音方式。例如：他说话带点口音 (He speaks with a slight accent)。" },
  { "accept", "接受 (jiēshòu) - 同意并接收某物。例如：我接受你的道歉 (I accept your apology)。" },
  { "acceptable", "可接受的 (kě jiēshòu de) - 令人满意的，可以被接受的。例如：这个价格是我们可以接受的 (This price is acceptable to us)。" },
  { "acceptance", "接受 (jiēshòu) - 同意或承认某事。例如：他对这个计划的接受，让大家都很高兴 (His acceptance of the plan made everyone happy)。" },
  { "accepted", "公认的 (gōngrèn de) - 被普遍承认或接受的。例如：这是一个公认的事实 (This is an accepted fact)。" },
  { "accepting", "接受 (jiēshòu) - 正在接受或愿意接受。例如：他正在接受新的挑战 (He is accepting new challenges)。" },
  { "accepts", "接受 (jiēshòu) - 接受（第三人称单数）。例如：他接受了我的建议 (He accepts my suggestion)。" },
  { "access", "访问 (fǎngwèn) - 使用或进入的权利或机会。例如：你需要密码才能访问这个网站 (You need a password to access this website)。" },
  { "accessed", "访问了 (fǎngwèn le) - 已经访问或进入。例如：他昨天访问了那个网站 (He accessed that website yesterday)。" },
  { "accessibility", "可访问性 (kě fǎngwèn xìng) - 指某物容易被访问或使用的程度。例如：我们致力于提高网站的可访问性 (We are committed to improving the accessibility of our website)。" },
  { "accessible", "可访问的 (kě fǎngwèn de) - 可以访问或进入的。例如：这个网站对所有用户都是可访问的 (This website is accessible to all users)。" },
  { "accessing", "正在访问 (zhèngzài fǎngwèn) - 正在进入或使用。例如：他正在访问一个安全的网站 (He is accessing a secure website)。" },
  { "accessories", "配件 (pèijiàn) - 附加到主要设备上的物品。例如：这个手机有很多配件 (This phone has many accessories)。" },
  { "accessory", "配饰 (pèishì) - 用于装饰的物品。例如：她戴着漂亮的发饰 (She is wearing a beautiful hair accessory)。" },
  { "accident", "事故 (shìgù) - 意外发生的、造成损失或伤害的事件。例如：他在一起交通事故中受伤了 (He was injured in a traffic accident)。" },
  { "accidents", "事故 (shìgù) - 意外发生的、造成损失或伤害的事件（复数）。例如：这里经常发生交通事故 (Traffic accidents often happen here)。" },
  { "accommodate", "容纳 (róngnà) - 为...提供住宿或空间。例如：这个酒店可以容纳200人 (This hotel can accommodate 200 people)。" },
  { "accommodation", "住宿 (zhùsù) - 指临时居住的地方，如旅馆、酒店等。例如：他们为他支付了机票和酒店住宿费用。 (They paid for his flights and hotel accommodation.)" },
  { "accommodations", "住宿 (zhùsù) - (复数) 指临时居住的地方，如旅馆、酒店等。例如：我们为所有与会者预订了住宿。 (We have booked accommodations for all attendees.)" },
  { "accompanied", "陪同 (péitóng) - 指与某人一同前往或停留。例如：旅行中他由妻子陪同。 (His wife accompanied him on the trip.)" },
  { "accompanying", "伴随的 (bànsuí de) - 指与某事物同时发生或存在。例如：抑郁症几乎总是伴有失眠。 (Depression is almost always accompanied by insomnia.)" },
  { "accomplish", "完成 (wánchéng) - 指成功地做完某事。例如：如果我们齐心协力，我想我们能完成我们的目标。 (If we all work together, I think we can accomplish our goal.)" },
  { "accomplished", "有造诣的 (yǒu zàoyì de) - 形容一个人在特定领域技能高超或才华横溢。例如：她是一位很有造诣的钢琴家。 (She is an accomplished pianist.)" },
  { "accordance", "按照 (ànzhào) - 通常用于“in accordance with”短语中，表示“根据”、“符合”。例如：按照她的遗愿，她被安葬在法国。 (In accordance with her wishes, she was buried in France.)" },
  { "according", "根据 (gēnjù) - 表示“依据”、“按照”。例如：根据我们的记录，你欠我们130美元。 (According to our records, you owe us $130.)" },
  { "accordingly", "因此 (yīncǐ) - 表示“所以”、“结果”。例如：这是一个困难的工作，他们应该得到相应的报酬。 (It is a difficult job and they should be paid accordingly.)" },
  { "account", "账户 (zhànghù) - 指银行账户、用户账号或记录。例如：我需要创建一个新账户 (I need to create a new account)。" },
  { "accountability", "问责制 (wènzé zhì) - 指对行为负责的义务。例如：公司强调问责制 (The company emphasizes accountability)。" },
  { "accounting", "会计 (kuàijì) - 指记录和报告财务信息的工作。例如：她在学习会计 (She is studying accounting)。" },
  { "accounts", "账目 (zhàngmù) - 账户的复数形式。例如：请检查所有账目 (Please check all accounts)。" },
  { "accreditation", "认证 (rènzhèng) - 指官方认可或授权。例如：这所大学获得了国家认证 (The university has national accreditation)。" },
  { "accredited", "获得认证的 (huòdé rènzhèng de) - 指经过官方认可的。例如：这是一所获得认证的机构 (This is an accredited institution)。" },
  { "accuracy", "准确性 (zhǔnquè xìng) - 指正确和精确的程度。例如：数据的准确性很重要 (The accuracy of the data is important)。" },
  { "accurate", "准确的 (zhǔnquè de) - 指正确无误的。例如：这是一个准确的描述 (This is an accurate description)。" },
  { "accurately", "准确地 (zhǔnquè de) - 指以精确的方式。例如：他准确地回答了问题 (He answered the question accurately)。" },
  { "accused", "被指控的 (bèi zhǐkòng de) - 指被指责犯有罪行的。例如：被告被指控盗窃 (The accused was charged with theft)。" },
  { "acdbentity", "AutoCAD数据库实体 (AutoCAD shùjùkù shítǐ) - AutoCAD软件中的数据库对象实体，用于表示图形中的各种元素。例如：该程序可以处理各种AutoCAD数据库实体 (The program can handle various AutoCAD database entities)。" },
  { "acer", "宏碁 (Hóngqí) - 台湾的一家知名电脑制造商，生产笔记本电脑、台式机和显示器等产品。例如：他买了一台宏碁笔记本电脑 (He bought an Acer laptop)。" },
  { "achieve", "实现 (shíxiàn) - 成功地完成或达到某个目标。例如：她通过努力工作实现了自己的梦想 (She achieved her dream through hard work)。" },
  { "achieved", "已实现的 (yǐ shíxiàn de) - 已经成功完成或达到的。例如：他已实现了预期的销售目标 (He has achieved the expected sales target)。" },
  { "achievement", "成就 (chéngjiù) - 通过努力获得的成功或完成的事情。例如：获得诺贝尔奖是他最大的成就 (Winning the Nobel Prize was his greatest achievement)。" },
  { "achievements", "成就 (chéngjiù) - 成就的复数形式。例如：她在科学领域取得了许多重要成就 (She has made many important achievements in science)。" },
  { "achieving", "实现 (shíxiàn) - 正在完成或达到某个目标的过程。例如：他正在努力实现自己的目标 (He is working hard at achieving his goals)。" },
  { "acid", "酸 (suān) - 一种化学物质，pH值小于7，具有腐蚀性。例如：胃酸帮助消化食物 (Stomach acid helps digest food)。" },
  { "acids", "酸类 (suān lèi) - 酸的复数形式，指多种酸性物质。例如：这些酸类物质需要小心处理 (These acids need to be handled carefully)。" },
  { "acknowledge", "承认 (chéngrèn) - 接受或承认某事的真实性或存在。例如：他承认自己犯了错误 (He acknowledged his mistake)。" },
  { "acknowledged", "公认的 (gōngrèn de) - 被普遍承认或接受的。例如：他是公认的专家 (He is an acknowledged expert)。" },
  { "acne", "痤疮 (cuóchuāng) - 一种常见的皮肤问题，通常在青春期出现。例如：青少年常常受痤疮困扰 (Teenagers often suffer from acne)。" },
  { "acoustic", "声学的 (shēngxué de) - 与声音或听觉相关的。例如：他演奏了一首美妙的木吉他曲 (He played a beautiful acoustic guitar song)。" },
  { "acquire", "获得 (huòdé) - 通过努力或购买得到某物。例如：公司计划收购一家新企业 (The company plans to acquire a new business)。" },
  { "acquired", "获得的 (huòdé de) - 已经得到或学习到的。例如：他在旅行中获得了很多知识 (He acquired a lot of knowledge during his travels)。" },
  { "acquisition", "收购 (shōugòu) - 购买或获得的行为，尤指企业收购。例如：这次收购耗资数百万美元 (The acquisition cost millions of dollars)。" },
  { "acquisitions", "收购 (shōugòu) - 收购的复数形式。例如：公司今年完成了多次收购 (The company completed multiple acquisitions this year)。" },
  { "acre", "英亩 (yīngmǔ) - 面积单位，约等于4047平方米。例如：这个农场占地50英亩 (The farm covers 50 acres)。" },
  { "acres", "英亩 (yīngmǔ) - 英亩的复数形式。例如：他们拥有数百英亩土地 (They own hundreds of acres of land)。" },
  { "acrobat", "杂技演员 (zájì yǎnyuán) - 表演体操和平衡技巧的人；也指Adobe的PDF阅读软件。例如：这位杂技演员表演了惊人的空中翻转 (The acrobat performed amazing aerial flips)。" },
  { "across", "穿过 (chuānguò) - 从一边到另一边。例如：他们走过了那座桥 (They walked across the bridge)。" },
  { "acrylic", "丙烯酸 (bǐngxīsuān) - 一种合成材料或颜料。例如：她用丙烯颜料画画 (She paints with acrylic paints)。" },
  { "acting", "表演 (biǎoyǎn) - 演戏的艺术或行为；也指代理的、临时的。例如：他在学习表演 (He is studying acting)。" },
  { "action", "行动 (xíngdòng) - 做某事的过程或行为。例如：我们需要立即采取行动 (We need to take action immediately)。" },
  { "actions", "行为 (xíngwéi) - 行动的复数形式。例如：他的行为说明了一切 (His actions speak louder than words)。" },
  { "activated", "激活的 (jīhuó de) - 已经启动或触发的。例如：该账户已被激活 (The account has been activated)。" },
  { "activation", "激活 (jīhuó) - 启动或启用某物的过程。例如：产品激活需要许可证密钥 (Product activation requires a license key)。" },
  { "active", "活跃的 (huóyuè de) - 积极参与的或正在运作的。例如：他是一个活跃的社区成员 (He is an active community member)。" },
  { "actively", "积极地 (jījí de) - 以活跃或主动的方式。例如：她积极参与志愿活动 (She actively participates in volunteer activities)。" },
  { "activists", "活动家 (huódòngjiā) - 积极参与社会或政治运动的人。例如：环保活动家呼吁保护森林 (Environmental activists call for forest protection)。" },
  { "activities", "活动 (huódòng) - 各种行为或事件的总称。例如：学校组织了许多课外活动 (The school organized many extracurricular activities)。" },
  { "activity", "活动 (huódòng) - 特定的行为或事件。例如：体育活动对健康有益 (Physical activity is beneficial to health)。" },
  { "actor", "演员 (yǎnyuán) - 在电影、戏剧或电视中表演的男性演员。例如：他是一位著名的电影演员 (He is a famous movie actor)。" },
  { "actors", "演员 (yǎnyuán) - 演员的复数形式。例如：这部电影有很多优秀的演员 (This movie has many excellent actors)。" },
  { "actress", "女演员 (nǚ yǎnyuán) - 在电影、戏剧或电视中表演的女性演员。例如：她是一位获奖的女演员 (She is an award-winning actress)。" },
  { "acts", "行为 (xíngwéi) - 行动或法案的复数形式。例如：善意的行为能改变世界 (Acts of kindness can change the world)。" },
  { "actual", "实际的 (shíjì de) - 真实的或确实存在的。例如：实际成本比预期高 (The actual cost was higher than expected)。" },
  { "actually", "实际上 (shíjì shàng) - 事实上，用于强调真实情况。例如：实际上，我已经完成了 (Actually, I have already finished)。" },
  { "acute", "急性的 (jíxìng de) - 严重的、尖锐的或突然发作的。例如：他患有急性支气管炎 (He has acute bronchitis)。" },
  { "adam", "亚当 (Yàdāng) - 男性名字；《圣经》中的第一个人类。例如：亚当是一个常见的英文名 (Adam is a common English name)。" },
  { "adams", "亚当斯 (Yàdāngsī) - 常见的英文姓氏。例如：约翰·亚当斯是美国第二任总统 (John Adams was the second U.S. President)。" },
  { "adaptation", "改编 (gǎibiān) - 对某物进行调整以适应新情况。例如：这部电影是小说的改编 (This movie is an adaptation of the novel)。" },
  { "adapted", "改编的 (gǎibiān de) - 已经调整或修改的。例如：这个故事被改编成了电视剧 (The story was adapted into a TV series)。" },
  { "adapter", "适配器 (shìpèiqì) - 用于连接不同设备的装置。例如：我需要一个电源适配器 (I need a power adapter)。" },
  { "adapters", "适配器 (shìpèiqì) - 适配器的复数形式。例如：这些适配器兼容多种设备 (These adapters are compatible with multiple devices)。" },
  { "adaptive", "自适应的 (zì shìyìng de) - 能够调整以适应变化的。例如：该系统具有自适应学习功能 (The system has adaptive learning capabilities)。" },
  { "adaptor", "适配器 (shìpèiqì) - adapter的另一种拼写。例如：请使用正确的适配器 (Please use the correct adaptor)。" },
  { "added", "添加的 (tiānjiā de) - 已经加入或增加的。例如：新功能已添加到应用中 (New features have been added to the app)。" },
  { "addiction", "上瘾 (shàngyǐn) - 对某物的强烈依赖或沉迷。例如：他正在戒除烟瘾 (He is overcoming his smoking addiction)。" },
  { "adding", "添加 (tiānjiā) - 正在增加或加入。例如：我正在添加更多信息 (I am adding more information)。" },
  { "addition", "增加 (zēngjiā) - 加入新事物的行为；加法运算。例如：除此之外，我们还需要更多时间 (In addition, we need more time)。" },
  { "additional", "额外的 (éwài de) - 更多的或补充的。例如：我们需要额外的资源 (We need additional resources)。" },
  { "additionally", "此外 (cǐwài) - 除了已经提到的之外。例如：此外，项目还需要更多资金 (Additionally, the project needs more funding)。" },
  { "additions", "增加物 (zēngjiā wù) - 增加的事物或部分。例如：房屋的增加部分包括一个新车库 (The additions to the house include a new garage)。" },
  { "address", "地址 (dìzhǐ) - 居住或办公地点；也指处理或解决问题。例如：请提供你的邮寄地址 (Please provide your mailing address)。" },
  { "addressed", "已解决的 (yǐ jiějué de) - 已经处理或提到的。例如：这个问题已被解决 (The issue has been addressed)。" },
  { "addresses", "地址 (dìzhǐ) - 地址的复数形式；也指演讲或处理。例如：请更新所有电子邮件地址 (Please update all email addresses)。" },
  { "addressing", "处理 (chǔlǐ) - 正在解决或谈论。例如：我们正在处理这个问题 (We are addressing this issue)。" },
  { "adds", "增加 (zēngjiā) - 添加或加上（第三人称单数）。例如：这个功能增加了便利性 (This feature adds convenience)。" },
  { "adelaide", "阿德莱德 (Ādéláidé) - 澳大利亚南澳大利亚州的首府城市。例如：阿德莱德以其葡萄酒产业闻名 (Adelaide is famous for its wine industry)。" },
  { "adequate", "足够的 (zúgòu de) - 数量或质量满足需求的。例如：我们有足够的资源完成项目 (We have adequate resources to complete the project)。" },
  { "adidas", "阿迪达斯 (Ādídásī) - 德国著名运动品牌，生产运动鞋、服装和配件。例如：他穿着一双阿迪达斯运动鞋 (He wore a pair of Adidas sneakers)。" },
  { "adipex", "阿地芬 (Ādìfēn) - 一种处方减肥药物的商品名。例如：医生为她开了阿地芬处方 (The doctor prescribed Adipex for her)。" },
  { "adjacent", "相邻的 (xiānglín de) - 紧挨着的或附近的。例如：他们的房子与我们的相邻 (Their house is adjacent to ours)。" },
  { "adjust", "调整 (tiáozhěng) - 改变以适应新情况。例如：请调整你的时间表 (Please adjust your schedule)。" },
  { "adjustable", "可调节的 (kě tiáojié de) - 可以改变或修改的。例如：这把椅子是可调节高度的 (This chair has an adjustable height)。" },
  { "adjusted", "调整后的 (tiáozhěng hòu de) - 已经修改或适应的。例如：价格已根据通货膨胀调整 (The price has been adjusted for inflation)。" },
  { "adjustment", "调整 (tiáozhěng) - 进行改变的行为或结果。例如：我们需要对计划做一些调整 (We need to make some adjustments to the plan)。" },
  { "adjustments", "调整 (tiáozhěng) - 调整的复数形式。例如：系统需要多次调整 (The system needs several adjustments)。" },
  { "admin", "管理员 (guǎnlǐyuán) - administrator的缩写，管理系统或网站的人。例如：请联系管理员获取权限 (Please contact the admin for permissions)。" },
  { "administered", "管理的 (guǎnlǐ de) - 已经管理或执行的。例如：该项目由政府管理 (The project was administered by the government)。" },
  { "administration", "管理 (guǎnlǐ) - 管理组织或执行任务；也指政府。例如：公司管理层做出了决定 (The company administration made the decision)。" },
  { "administrative", "行政的 (xíngzhèng de) - 与管理或行政工作相关的。例如：她从事行政工作 (She does administrative work)。" },
  { "administrator", "管理员 (guǎnlǐyuán) - 管理系统、组织或财产的人。例如：系统管理员负责维护服务器 (The system administrator maintains the servers)。" },
  { "administrators", "管理员 (guǎnlǐyuán) - 管理员的复数形式。例如：所有管理员都收到了通知 (All administrators received the notification)。" },
  { "admission", "入场 (rùchǎng) - 进入某地或被接纳的权利；也指承认。例如：博物馆门票免费 (Admission to the museum is free)。" },
  { "admissions", "招生 (zhāoshēng) - 接纳新成员的过程，尤指学校招生。例如：大学招生办公室很忙 (The university admissions office is busy)。" },
  { "admit", "承认 (chéngrèn) - 接受事实为真或允许进入。例如：他承认自己错了 (He admitted he was wrong)。" },
  { "admitted", "被接纳的 (bèi jiēnà de) - 已经被允许进入或承认的。例如：她被哈佛大学录取了 (She was admitted to Harvard University)。" },
  { "adobe", "Adobe公司 (Adobe gōngsī) - 美国软件公司，以Photoshop、PDF等产品著名；也指土坯。例如：我用Adobe Photoshop编辑图片 (I edit images with Adobe Photoshop)。" },
  { "adolescent", "青少年 (qīngshàonián) - 处于青春期的年轻人。例如：青少年需要指导和支持 (Adolescents need guidance and support)。" },
  { "adopt", "采用 (cǎiyòng) - 接受并开始使用；也指收养。例如：公司采用了新策略 (The company adopted a new strategy)。" },
  { "adopted", "采用的 (cǎiyòng de) - 已经接受或收养的。例如：他们收养了一个孩子 (They adopted a child)。" },
  { "adoption", "采用 (cǎiyòng) - 采纳或收养的行为。例如：新技术的采用需要时间 (The adoption of new technology takes time)。" },
  { "adrian", "阿德里安 (Ādélǐ'ān) - 常见的英文男性名字。例如：阿德里安是我的同事 (Adrian is my colleague)。" },
  { "adsl", "非对称数字用户线路 (fēi duìchèn shùzì yònghù xiànlù) - 一种宽带互联网连接技术，缩写为ADSL。例如：我们使用ADSL上网 (We use ADSL for internet access)。" },
  { "adult", "成年人 (chéngniánrén) - 已经成熟的人，通常指18岁以上。例如：这部电影仅供成年人观看 (This movie is for adults only)。" },
  { "adults", "成年人 (chéngniánrén) - 成年人的复数形式。例如：成年人需要为自己的行为负责 (Adults are responsible for their own actions)。" },
  { "advance", "前进 (qiánjìn) - 向前移动或提前；也指进步。例如：我们需要提前预订 (We need to book in advance)。" },
  { "advanced", "先进的 (xiānjìn de) - 高级的或发达的。例如：他学习高级数学 (He studies advanced mathematics)。" },
  { "advancement", "进步 (jìnbù) - 向前发展或提升。例如：技术进步改变了我们的生活 (Technological advancement has changed our lives)。" },
  { "advances", "进展 (jìnzhǎn) - 前进或进步的复数形式。例如：医学取得了重大进展 (Medicine has made significant advances)。" },
  { "advantage", "优势 (yōushì) - 有利条件或好处。例如：这给了我们竞争优势 (This gives us a competitive advantage)。" },
  { "advantages", "优势 (yōushì) - 优势的复数形式。例如：这个方案有很多优势 (This plan has many advantages)。" },
  { "adventure", "冒险 (màoxiǎn) - 令人兴奋或危险的经历。例如：他们去亚马逊探险 (They went on an adventure to the Amazon)。" },
  { "adventures", "冒险 (màoxiǎn) - 冒险的复数形式。例如：他写了一本关于他冒险经历的书 (He wrote a book about his adventures)。" },
  { "adverse", "不利的 (bùlì de) - 有害的或不想要的。例如：药物可能有不利副作用 (The medicine may have adverse side effects)。" },
  { "advert", "广告 (guǎnggào) - advertisement的缩写，尤其在英式英语中使用。例如：我在报纸上看到了一则招聘广告 (I saw a job advert in the newspaper)。" },
  { "advertise", "打广告 (dǎ guǎnggào) - 公开宣传产品或服务。例如：公司在电视上打广告 (The company advertises on TV)。" },
  { "advertisement", "广告 (guǎnggào) - 用于推广产品或服务的公告。例如：这个广告很有创意 (This advertisement is very creative)。" },
  { "advertisements", "广告 (guǎnggào) - 广告的复数形式。例如：报纸上有很多广告 (There are many advertisements in the newspaper)。" },
  { "advertiser", "广告商 (guǎnggào shāng) - 付费做广告的个人或公司。例如：广告商支付了高额费用 (The advertiser paid a high fee)。" },
  { "advertisers", "广告商 (guǎnggào shāng) - 广告商的复数形式。例如：许多广告商参加了会议 (Many advertisers attended the conference)。" },
  { "advertising", "广告业 (guǎnggào yè) - 广告的行业或活动。例如：她在广告业工作 (She works in advertising)。" },
  { "advice", "建议 (jiànyì) - 对某人应该做什么的意见。例如：我需要你的建议 (I need your advice)。" },
  { "advise", "建议 (jiànyì) - 给予建议或劝告。例如：我建议你早点出发 (I advise you to leave early)。" },
  { "advised", "被告知的 (bèi gàozhī de) - 已经得到建议或通知的。例如：他被告知要小心 (He was advised to be careful)。" },
  { "advisor", "顾问 (gùwèn) - 提供建议的人。例如：他是我的学术顾问 (He is my academic advisor)。" },
  { "advisors", "顾问 (gùwèn) - 顾问的复数形式。例如：公司有多位财务顾问 (The company has several financial advisors)。" },
  { "advisory", "顾问的 (gùwèn de) - 提供建议的；也指咨询委员会。例如：顾问委员会开会了 (The advisory board met)。" },
  { "advocacy", "倡导 (chàngdǎo) - 公开支持某个事业或政策。例如：她从事环保倡导工作 (She works in environmental advocacy)。" },
  { "advocate", "提倡 (tíchàng) - 公开支持或推荐；也指辩护人。例如：他提倡改革 (He advocates for reform)。" },
  { "adware", "广告软件 (guǎnggào ruǎnjiàn) - 自动显示广告的软件。例如：这个程序包含广告软件 (This program contains adware)。" },
  { "aerial", "空中的 (kōngzhōng de) - 在空中的或与飞行相关的。例如：无人机进行了空中拍摄 (The drone took aerial photographs)。" },
  { "aerospace", "航空航天 (hángkōng hángtiān) - 与飞机和航天器相关的工业。例如：他在航空航天公司工作 (He works for an aerospace company)。" },
  { "affair", "事务 (shìwù) - 事件或情况；也指婚外情。例如：这是私人事务 (This is a private affair)。" },
  { "affairs", "事务 (shìwù) - 事务的复数形式。例如：外交事务很复杂 (Foreign affairs are complex)。" },
  { "affect", "影响 (yǐngxiǎng) - 对某事物产生作用或改变。例如：天气会影响我们的计划 (The weather will affect our plans)。" },
  { "affected", "受影响的 (shòu yǐngxiǎng de) - 已经被影响的。例如：许多人受到了洪水的影响 (Many people were affected by the flood)。" },
  { "affecting", "影响 (yǐngxiǎng) - 正在产生影响。例如：这个问题正在影响我们的业务 (This issue is affecting our business)。" },
  { "affects", "影响 (yǐngxiǎng) - 影响（第三人称单数）。例如：压力影响健康 (Stress affects health)。" },
  { "affiliate", "附属机构 (fùshǔ jīgòu) - 与较大组织有联系的组织；也指关联方。例如：这是我们的附属公司 (This is our affiliate company)。" },
  { "affiliated", "附属的 (fùshǔ de) - 与组织有正式联系的。例如：他附属于那所大学 (He is affiliated with that university)。" },
  { "affiliates", "附属机构 (fùshǔ jīgòu) - 附属机构的复数形式。例如：公司在全球有多个附属机构 (The company has affiliates worldwide)。" },
  { "affiliation", "隶属关系 (lìshǔ guānxì) - 与组织的正式联系。例如：请注明你的机构隶属关系 (Please state your institutional affiliation)。" },
  { "afford", "负担得起 (fùdān dé qǐ) - 有足够的钱购买；也指提供。例如：我买不起这辆车 (I cannot afford this car)。" },
  { "affordable", "负担得起的 (fùdān dé qǐ de) - 价格合理的。例如：我们需要负担得起的住房 (We need affordable housing)。" },
  { "afghanistan", "阿富汗 (Āfùhàn) - 亚洲中部国家。例如：阿富汗是一个多山的国家 (Afghanistan is a mountainous country)。" },
  { "afraid", "害怕的 (hàipà de) - 感到恐惧或担心。例如：我害怕黑暗 (I am afraid of the dark)。" },
  { "africa", "非洲 (Fēizhōu) - 世界第二大洲。例如：非洲有丰富的野生动物 (Africa has abundant wildlife)。" },
  { "african", "非洲的 (Fēizhōu de) - 来自或与非洲相关的。例如：他研究非洲历史 (He studies African history)。" },
  { "after", "在...之后 (zài...zhīhòu) - 表示时间或顺序的后面。例如：午饭后我们去散步 (We go for a walk after lunch)。" },
  { "afternoon", "下午 (xiàwǔ) - 中午到傍晚之间的时间。例如：我们下午见 (See you in the afternoon)。" },
  { "afterwards", "后来 (hòulái) - 在那之后。例如：我们先吃饭，后来看了电影 (We ate first, and watched a movie afterwards)。" },
