  { "against", "反对 (fǎnduì) - 与...相对或相反。例如：我们反对这个决定 (We are against this decision)。" },
  { "aged", "年老的 (niánlǎo de) - 特定年龄的或年老的。例如：她照顾年老的父母 (She cares for her aged parents)。" },
  { "agencies", "机构 (jīgòu) - 机构的复数形式。例如：政府机构负责监管 (Government agencies are responsible for regulation)。" },
