  { "agents", "代理人 (dàilǐrén) - 代理人的复数形式。例如：保险代理人提供咨询服务 (Insurance agents provide consulting services)。" },
  { "ages", "年龄 (niánlíng) - 年龄的复数形式；也指很长时间。例如：我们等了好久 (We waited for ages)。" },
  { "aggregate", "总计 (zǒngjì) - 总和或集合；也指合计的。例如：总销售额达到了一百万 (The aggregate sales reached one million)。" },
  { "aggressive", "激进的 (jījìn de) - 好斗的或积极进取的。例如：公司采取了激进的扩张策略 (The company adopted an aggressive expansion strategy)。" },
  { "aging", "老化 (lǎohuà) - 变老的过程。例如：人口老化是一个社会问题 (Population aging is a social issue)。" },
