  { "agriculture", "农业 (nóngyè) - 种植作物和饲养动物的科学或实践。例如：农业是国家经济的基础 (Agriculture is the foundation of the national economy)。" },
  { "ahead", "在前面 (zài qiánmiàn) - 在前方或提前。例如：你走在我前面 (You are ahead of me)。" },
