  { "airfare", "机票价格 (jīpiào jiàgé) - 乘坐飞机的费用。例如：机票价格很贵 (The airfare is expensive)。" },
  { "airline", "航空公司 (hángkōng gōngsī) - 提供航空运输服务的公司。例如：我在这家航空公司订了票 (I booked with this airline)。" },
  { "airlines", "航空公司 (hángkōng gōngsī) - 航空公司的复数形式。例如：许多航空公司提供国际航班 (Many airlines offer international flights)。" },
