  { "alarm", "警报 (jǐngbào) - 警告危险的信号或装置。例如：火灾警报响了 (The fire alarm went off)。" },
  { "alaska", "阿拉斯加州 (Ālāsījiā zhōu) - 美国最北端的州。例如：阿拉斯加州以冰川著名 (Alaska is famous for its glaciers)。" },
  { "albania", "阿尔巴尼亚 (Ā'ěrbāníyà) - 欧洲东南部国家。例如：阿尔巴尼亚位于巴尔干半岛 (Albania is located in the Balkans)。" },
  { "albany", "奥尔巴尼 (Ào'ěrbāní) - 纽约州首府城市。例如：奥尔巴尼是纽约州的政治中心 (Albany is the political center of New York State)。" },
  { "albert", "阿尔伯特 (Ā'ěrbótè) - 常见的英文男性名字。例如：阿尔伯特·爱因斯坦是著名物理学家 (Albert Einstein was a famous physicist)。" },
  { "alberta", "阿尔伯塔省 (Ā'ěrbótǎ shěng) - 加拿大西部省份。例如：阿尔伯塔省盛产石油 (Alberta produces abundant oil)。" },
