  { "albuquerque", "阿尔伯克基 (Ā'ěrbókèjī) - 美国新墨西哥州最大城市。例如：阿尔伯克基以热气球节闻名 (Albuquerque is famous for its balloon festival)。" },
  { "alcohol", "酒精 (jiǔjīng) - 含有乙醇的饮料或化学物质。例如：过量饮酒对健康有害 (Excessive alcohol consumption is harmful to health)。" },
  { "alert", "警报 (jǐngbào) - 警告或保持警惕的；也指警告通知。例如：系统发出了安全警报 (The system issued a security alert)。" },
  { "alerts", "警报 (jǐngbào) - 警报的复数形式。例如：我收到了多个新闻警报 (I received multiple news alerts)。" },
